import 'package:flutter/material.dart';

import '../../models/share_content.dart';

/// A paper-white preview of the first page of the exported PDF.
///
/// The PDF itself is generated by [SharePdfService] with the same layout
/// (running head, title, byline, rules, justified body, citation, footer),
/// so the sheet can show what will be printed without rasterising a real
/// PDF on the platform. Content and proportions come from [content]; the
/// page is an A4 portrait.
class ShareDocumentPreview extends StatelessWidget {
  /// Design width; the widget is normally scaled down with a [FittedBox].
  final double width;
  final ShareContent content;

  const ShareDocumentPreview({
    super.key,
    required this.content,
    this.width = 620,
  });

  // Fixed artwork: this preview must look like the printed page no matter
  // which app theme is active.
  /// Bundle serif used for body copy (Cardo also backs the PDF).
  static const _serif = 'Cardo';

  /// Proper noun, untranslated — same line as the PDF footer.
  static const _brand = 'The Blessed Bible';

  static const _paper = Color(0xFFFBF8F2);
  static const _ink = Color(0xFF191714);
  static const _muted = Color(0xFF6B635A);
  static const _rule = Color(0xFFDCD4C7);

  @override
  Widget build(BuildContext context) {
    final s = width / 620;
    final body = _bodyStyle(s);
    final title =
        content.kind == ShareKind.story ? content.title : content.reference;
    final meta = _metaLine();

    return Container(
      width: width,
      height: width * 1.414,
      decoration: BoxDecoration(
        color: _paper,
        border: Border.all(color: _rule, width: 1),
        boxShadow: const [
          BoxShadow(
            color: Color(0x22000000),
            blurRadius: 18,
            offset: Offset(0, 8),
          ),
        ],
      ),
      child: Padding(
        padding: EdgeInsets.all(52 * s),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: [
                Text(
                  _eyebrow(),
                  style: _sans(s * 7.6,
                      color: _muted, weight: FontWeight.w700, space: 2.4),
                ),
                Text(
                  'THE BLESSED BIBLE',
                  style: _sans(s * 7.2,
                      color: _muted, weight: FontWeight.w400, space: 1.8),
                ),
              ],
            ),
            SizedBox(height: 8 * s),
            Container(height: 0.8, color: _rule),
            SizedBox(height: 30 * s),
            if (title != null && title.isNotEmpty)
              Text(
                title,
                maxLines: 2,
                overflow: TextOverflow.ellipsis,
                style: TextStyle(
                  fontFamily: 'EB Garamond',
                  fontSize: 25 * s,
                  height: 1.15,
                  fontWeight: FontWeight.w600,
                  color: _ink,
                ),
              ),
            if (meta != null) ...[
              SizedBox(height: 6 * s),
              Text(
                meta,
                style: TextStyle(
                  fontFamily: _serif,
                  fontSize: 10.5 * s,
                  fontStyle: FontStyle.italic,
                  color: _muted,
                ),
              ),
            ],
            SizedBox(height: 14 * s),
            Container(height: 0.8, color: _rule),
            SizedBox(height: 18 * s),
            if (content.keyVerse != null && content.keyVerse!.isNotEmpty) ...[
              Text(
                '“${content.keyVerse!}”',
                maxLines: 3,
                overflow: TextOverflow.ellipsis,
                style: TextStyle(
                  fontFamily: _serif,
                  fontSize: 12.5 * s,
                  height: 1.5,
                  fontStyle: FontStyle.italic,
                  color: _ink,
                ),
              ),
              if (content.keyVerseRef != null &&
                  content.keyVerseRef!.isNotEmpty) ...[
                SizedBox(height: 3 * s),
                Text(
                  content.keyVerseRef!,
                  style: _sans(s * 6.8, color: _muted, space: 0.4),
                ),
              ],
              SizedBox(height: 14 * s),
            ],
            // Body takes the space it needs; overflow fades instead of
            // clipping hard, and the citation follows the last line exactly
            // as it does in the PDF.
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Flexible(
                    child: ClipRect(
                      child: Align(
                        alignment: Alignment.topLeft,
                        child: Text(
                          content.paragraphs.join('\n\n'),
                          maxLines: 18,
                          overflow: TextOverflow.fade,
                          textAlign: TextAlign.justify,
                          style: body,
                        ),
                      ),
                    ),
                  ),
                  if (content.kind != ShareKind.story &&
                      content.attribution != null) ...[
                    SizedBox(height: 10 * s),
                    Container(height: 0.8, width: 64 * s, color: _rule),
                    SizedBox(height: 7 * s),
                    Text(
                      '— ${content.attribution!}',
                      maxLines: 2,
                      overflow: TextOverflow.ellipsis,
                      style: TextStyle(
                        fontFamily: _serif,
                        fontSize: 9.5 * s,
                        fontStyle: FontStyle.italic,
                        color: _muted,
                      ),
                    ),
                  ],
                ],
              ),
            ),
            SizedBox(height: 12 * s),
            Container(
              padding: EdgeInsets.only(top: 7 * s),
              decoration: BoxDecoration(
                border: Border(top: BorderSide(color: _rule, width: 0.6)),
              ),
              child: Row(
                mainAxisAlignment: MainAxisAlignment.spaceBetween,
                children: [
                  Text(_brand, style: _sans(s * 7, color: _muted, space: 0.2)),
                  Text('1', style: _sans(s * 7, color: _muted, space: 0.2)),
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }

  TextStyle _bodyStyle(double s) => TextStyle(
        fontFamily: _serif,
        fontSize: 11.2 * s,
        height: 1.5,
        color: _ink,
      );

  TextStyle _sans(
    double size, {
    required Color color,
    FontWeight weight = FontWeight.w400,
    double space = 0,
  }) =>
      TextStyle(
        fontFamily: 'Inter',
        fontSize: size,
        fontWeight: weight,
        letterSpacing: space,
        color: color,
      );

  String _eyebrow() {
    if (content.eyebrow.isNotEmpty) return content.eyebrow.toUpperCase();
    return content.kind.name.toUpperCase();
  }

  /// Mirror of the PDF byline: reference for stories, date for daily items.
  String? _metaLine() {
    final date = content.date;
    if (content.kind == ShareKind.story) {
      final ref = content.reference;
      if (ref != null && ref.isNotEmpty) {
        return date == null ? ref : '$ref · $date';
      }
    }
    return date;
  }
}
